package vn.smartfarm.iot.control;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;
import vn.smartfarm.iot.nodes.*;import vn.smartfarm.iot.irrigation.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=true","smartfarm.control.pump-fencing-enabled=true","smartfarm.control.circuit-route-required=true","smartfarm.irrigation.circuit-demo-enabled=true","smartfarm.irrigation.session-enabled=true","smartfarm.irrigation.flow-stop-enabled=true","smartfarm.irrigation.flow-stop-poll-ms=3600000","smartfarm.irrigation.water-stop-enabled=true","smartfarm.irrigation.water-stop-poll-ms=3600000","smartfarm.irrigation.rain-stop-enabled=true","smartfarm.irrigation.rain-stop-poll-ms=3600000"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class CircuitFlowGuardTest {
 @Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired CircuitWaterGate gate;@Autowired CircuitFlowGuard flowGuard;@Autowired ZoneRainGate weatherGate;@Autowired NodeInventory nodes;@Autowired TelemetryRouter router;
 @Autowired PumpService pump;@Autowired PumpCommandFencing fencing;@Autowired PumpCircuitProof proof;@Autowired CircuitValveControl valves;@Autowired IrrigationCircuits circuits;@Autowired IrrigationSession sessions;@Autowired MockMvc mvc;@Autowired org.springframework.transaction.PlatformTransactionManager manager;
 @MockitoBean CommandTransport transport;@MockitoBean CircuitValveTransport valveTransport;
 UUID boot=UUID.fromString("83000000-0000-4000-8000-000000000001"),vboot=UUID.fromString("83000000-0000-4000-8000-000000000002");PumpCircuitRoute route;
 @BeforeEach void setup()throws Exception{
  cleanup();jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");reset(transport,valveTransport);when(transport.controlConnected()).thenReturn(true);when(valveTransport.circuitValveConnected(anyString())).thenReturn(true);
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('WGSOIL','Soil','AREA001','SOIL',2),('WGWATER','Water','AREA001','WATER',2)");
  for(int i=1;i<=3;i++)jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('WGSOIL',?,'SOIL_MOISTURE','%')","SOIL"+i);
  jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('WGWATER','LOW','WATER_PRESENT','boolean'),('WGWATER','FLOW','FLOW_RATE','L/min')");
  jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES('WGZONE','Zone','AREA001','WGSOIL','SIMULATOR',30,35)");
  jdbc.update("INSERT INTO irrigation_circuit(circuit_id,name,zone_id,zone_revision,controller_id,valve_id,pump_id,water_node_id,low_channel_id,flow_channel_id,expected_source) VALUES('WGC','Circuit','WGZONE',1,'IRRIGATION75','VALVE75','PUMP01','WGWATER','LOW','FLOW','SIMULATOR')");
  route=PumpCircuitRoute.from(circuits.find("WGC"));pumpStatus(1,0,"OFF");valveStatus(1,0,"CLOSED");
 }
 @AfterEach void after(){cleanup();jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");}
 void cleanup(){jdbc.update("DELETE FROM irrigation_flow_stop WHERE circuit_id='WGC'");jdbc.update("DELETE FROM irrigation_water_stop WHERE circuit_id='WGC'");jdbc.update("DELETE FROM irrigation_weather_stop WHERE zone_id='WGZONE'");jdbc.update("DELETE FROM irrigation_session_action WHERE session_id IN(SELECT session_id FROM irrigation_session WHERE circuit_id='WGC')");jdbc.update("DELETE FROM irrigation_session WHERE circuit_id='WGC'");for(String t:List.of("circuit_demo_command","circuit_demo_status","circuit_demo_boot","circuit_demo_gate"))jdbc.update("DELETE FROM "+t+" WHERE valve_id='VALVE75'");jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id='WGC'");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id='WGZONE'");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('WGSOIL','WGWATER','WGWEATHER','WGOTHER')");jdbc.update("DELETE FROM sensor_area WHERE id='WGAREA'");}
 void pumpStatus(long seq,long ordinal,String state)throws Exception {var p=mapper.createObjectNode().put("schemaVersion",1).put("deviceId","PUMP01").put("bootId",boot.toString()).put("sequence",seq).put("timestamp",Instant.now().toString()).put("connection","ONLINE").put("reportedState",state).put("safetyLockout",false).put("stateReason",state.equals("ON")?"COMMAND_ON":"COMMAND_OFF");p.putObject("commandFence").put("version",1).put("lastOrdinal",ordinal).put("restartRequired",false);p.putObject("valveInterlock").put("version",1).put("enabled",true).put("dataSource","SIMULATOR").put("state","OPEN").putNull("fault").set("route",mapper.valueToTree(route));pump.receive("smartfarm/FARM001/PUMP01/status",mapper.writeValueAsBytes(p));}
 ObjectNode valvePacket(long seq,long ordinal,String state){var c=circuits.find("WGC");var p=mapper.createObjectNode().put("schemaVersion",1).put("controlProfile",CircuitValveControl.PROFILE).put("controllerId",c.controllerId()).put("actuatorId",c.valveId()).put("circuitId",c.circuitId()).put("circuitRevision",1).put("zoneId",c.zoneId()).put("zoneRevision",1).put("bootId",vboot.toString()).put("sequence",seq).put("timestamp",Instant.now().toString()).put("dataSource","SIMULATOR").put("feedbackState",state).put("gpioState",state).put("reason",state.equals("OPEN")?"COMMAND_OPEN":"COMMAND_CLOSE").put("demoEnabled",true).put("lastOrdinal",ordinal);p.putObject("positionFeedback").put("version",1).put("enabled",true).put("state",state).putNull("fault");return p;}
 void valveStatus(long seq,long ordinal,String state)throws Exception {valves.receive(CircuitValveControl.topic("VALVE75","status"),mapper.writeValueAsBytes(valvePacket(seq,ordinal,state)),false);}
 void open()throws Exception {var c=valves.create("WGC",new CircuitValveControl.Request(UUID.randomUUID(),"OPEN",30,vboot,1,1,Instant.now()));var p=valvePacket(2,c.ordinal(),"OPEN").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","OPEN").put("result","EXECUTED").putNull("errorCode");valves.receive(CircuitValveControl.topic("VALVE75","ack"),mapper.writeValueAsBytes(p),false);valveStatus(3,c.ordinal(),"OPEN");}
 PumpCommandFencing.HttpIntent intent(String action){var c=fencing.view().intent();return new PumpCommandFencing.HttpIntent(UUID.randomUUID(),action,action.equals("ON")?5:null,action.equals("OFF")?null:boot,c.revision(),c.asOf(),action.equals("OFF")?null:route);}
 CircuitWaterGate.Request request(int revision,boolean enabled){return new CircuitWaterGate.Request(revision,1,null,enabled);}
 void enable(){gate.save("WGC",request(0,true));}
 ObjectNode packet(long seq,Boolean present,Instant at)throws Exception {var p=(ObjectNode)mapper.readTree(getClass().getResourceAsStream("/water-firmware-packet.json"));p.put("deviceId","WGWATER").put("sequence",seq).put("timestamp",at.toString());p.withArray("readings").remove(1);var r=(ObjectNode)p.path("readings").get(0);if(present==null)r.put("quality","SENSOR_FAULT").putNull("value");else r.put("value",present);return p;}
 void water(long seq,Boolean present,Instant at)throws Exception {router.store("smartfarm/FARM001/WGWATER/telemetry",mapper.writeValueAsBytes(packet(seq,present,at)));}
 IrrigationSession.Run begun()throws Exception {water(1,true,Instant.now());var v=sessions.snapshot("WGC");return sessions.start("WGC",new IrrigationSession.Start(UUID.randomUUID(),1,1,boot,vboot,5,v.asOf()));}
 IrrigationSession.Run step(IrrigationSession.Run r,String action){return sessions.act("WGC",r.sessionId(),new IrrigationSession.Action(UUID.randomUUID(),action,r.revision(),Instant.now())).session();}
 IrrigationSession.Run beforeOn()throws Exception {var r=step(begun(),"OPEN");var c=valves.lookup("WGC",r.openId());var p=valvePacket(2,c.ordinal(),"OPEN").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","OPEN").put("result","EXECUTED").putNull("errorCode");valves.receive(CircuitValveControl.topic("VALVE75","ack"),mapper.writeValueAsBytes(p),false);valveStatus(3,c.ordinal(),"OPEN");return r;}
 IrrigationSession.Run running()throws Exception {return step(beforeOn(),"ON");}
 CircuitFlowGuard.Request flowRequest(int revision,boolean enabled){return new CircuitFlowGuard.Request(revision,1,null,enabled,2,1);}
 void flowPolicy(){flowGuard.save("WGC",flowRequest(0,true));}
 int stops(){return jdbc.queryForObject("SELECT count(*) FROM irrigation_flow_stop WHERE circuit_id='WGC'",Integer.class);}
 void afterGrace(IrrigationSession.Run r){jdbc.update("UPDATE irrigation_session_action SET created_at=CURRENT_TIMESTAMP-INTERVAL '2 seconds' WHERE request_id=?",r.onId());}
 void flow(long seq,Double value,Instant at)throws Exception {var p=(ObjectNode)mapper.readTree(getClass().getResourceAsStream("/water-firmware-packet.json"));p.put("deviceId","WGWATER").put("sequence",seq).put("timestamp",at.toString());var reading=p.withArray("readings").get(2).deepCopy();p.withArray("readings").removeAll().add(reading);var r=(ObjectNode)reading;if(value==null)r.put("quality","SENSOR_FAULT").putNull("value");else r.put("value",value);router.store("smartfarm/FARM001/WGWATER/telemetry",mapper.writeValueAsBytes(p));}
 JsonNode evidence()throws Exception{return mapper.readTree(jdbc.queryForObject("SELECT evidence::text FROM irrigation_flow_stop",String.class));}
 @Test void defaultsAreDisabledAndDoNotInventFlowProof()throws Exception {assertEquals("NOT_CONFIGURED",flowGuard.snapshot("WGC").state());var r=running();afterGrace(r);sessions.stopForFlow();assertEquals(0,stops());flowGuard.snapshot("WGC");verify(transport,times(1)).publishCommand(any());}
 @Test void profileAndBoundsAreRequired(){assertThrows(Exception.class,()->new CircuitFlowGuard(jdbc,true,true,true,true,true,false).save("WGC",flowRequest(0,true)));for(double rate:new double[]{0,-1,1001,Double.NaN,Double.POSITIVE_INFINITY})assertThrows(Exception.class,()->flowGuard.save("WGC",new CircuitFlowGuard.Request(0,1,null,true,rate,1)));for(int grace:new int[]{0,9})assertThrows(Exception.class,()->flowGuard.save("WGC",new CircuitFlowGuard.Request(0,1,null,true,2,grace)));}
 @Test void policyRequiresCurrentCalibrationRevisionAndIdle()throws Exception {assertThrows(Exception.class,()->flowGuard.save("WGC",new CircuitFlowGuard.Request(0,1,"OTHER",true,2,1)));flowPolicy();assertThrows(Exception.class,()->flowGuard.save("WGC",flowRequest(0,false)));running();assertThrows(Exception.class,()->flowGuard.save("WGC",flowRequest(1,false)));}
 @Test void graceCannotHideWholeSession()throws Exception {flowGuard.save("WGC",new CircuitFlowGuard.Request(0,1,null,true,2,5));assertThrows(Exception.class,()->begun());verify(transport,never()).publishCommand(any());}
 @Test void preparedAndGraceDoNotStopAndBoundaryIsExact()throws Exception {flowPolicy();var r=beforeOn();assertEquals("IDLE",flowGuard.snapshot("WGC").state());sessions.stopForFlow();r=step(r,"ON");var v=flowGuard.snapshot("WGC");assertEquals("GRACE",v.state());sessions.stopForFlow();assertEquals("GRACE",CircuitFlowGuard.inspect(jdbc,"WGC",v.graceUntil().minusNanos(1),true).state());assertEquals("BEFORE_ON",CircuitFlowGuard.inspect(jdbc,"WGC",v.graceUntil(),true).state());assertEquals(0,stops());}
 @Test void postOnFlowAtThresholdAllowsAndZeroStopsOnce()throws Exception {flowPolicy();var r=running();afterGrace(r);flow(2,2.0,Instant.now());assertEquals("FLOW_OK",flowGuard.snapshot("WGC").state());sessions.stopForFlow();assertEquals(0,stops());flow(3,0.0,Instant.now());sessions.stopForFlow();assertEquals("LOW_FLOW",evidence().path("state").asText());assertEquals(1,stops());var stopped=sessions.find("WGC",r.sessionId());assertTrue(stopped.stopRequested());assertEquals("WAIT_OFF",stopped.phase());flow(4,4.0,Instant.now());sessions.stopForFlow();assertEquals(1,stops());assertFalse(sessions.snapshot("WGC").canOn());verify(transport,times(2)).publishCommand(any());}
 @Test void preOnFlowAndLowOnlyCannotRefreshFlow()throws Exception {flowPolicy();var r=running();afterGrace(r);jdbc.update("UPDATE node_sample SET observed_at=CURRENT_TIMESTAMP-INTERVAL '3 seconds' WHERE node_id='WGWATER'");var low=packet(2,true,Instant.now());low.withArray("readings").remove(1);router.store("smartfarm/FARM001/WGWATER/telemetry",mapper.writeValueAsBytes(low));sessions.stopForFlow();assertEquals("BEFORE_ON",evidence().path("state").asText());}
 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(strings={"MISSING","SENSOR_FAULT","SOURCE_MISMATCH","CALIBRATION_MISMATCH","CLOCK_SKEW","CONFIG_CHANGED","CHANNEL_UNAVAILABLE","ANCHOR_MISSING"})
 void invalidFlowStopsWithSpecificEvidence(String state)throws Exception {flowPolicy();var r=running();afterGrace(r);flow(2,5.0,Instant.now());switch(state){case "MISSING"->jdbc.update("DELETE FROM channel_sample WHERE node_id='WGWATER' AND channel_id='FLOW'");case "SENSOR_FAULT"->flow(3,null,Instant.now());case "SOURCE_MISMATCH"->jdbc.update("UPDATE node_sample SET data_source='PHYSICAL' WHERE node_id='WGWATER'");case "CALIBRATION_MISMATCH"->jdbc.update("UPDATE channel_sample SET calibration_version='OTHER' WHERE node_id='WGWATER' AND channel_id='FLOW'");case "CLOCK_SKEW"->jdbc.update("UPDATE node_sample SET observed_at=CURRENT_TIMESTAMP+INTERVAL '3 seconds' WHERE node_id='WGWATER'");case "CONFIG_CHANGED"->jdbc.update("UPDATE irrigation_circuit SET revision=2 WHERE circuit_id='WGC'");case "CHANNEL_UNAVAILABLE"->jdbc.update("UPDATE iot_channel SET metric='WATER_PRESSURE',unit='kPa' WHERE node_id='WGWATER' AND channel_id='FLOW'");case "ANCHOR_MISSING"->jdbc.update("DELETE FROM irrigation_session_action WHERE request_id=?",r.onId());}sessions.stopForFlow();assertEquals(state,evidence().path("state").asText());assertTrue(evidence().path("stopRequired").asBoolean());assertEquals(1,stops());}
 @Test void tenSecondFreshnessUsesBothClocksAndExactBoundary()throws Exception {flowPolicy();var r=running();afterGrace(r);Instant at=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);flow(2,5.0,at);jdbc.update("UPDATE node_sample SET received_at=? WHERE node_id='WGWATER' AND sequence=2",java.sql.Timestamp.from(at));assertEquals("FLOW_OK",CircuitFlowGuard.inspect(jdbc,"WGC",at.plusSeconds(9),true).state());assertEquals("STALE",CircuitFlowGuard.inspect(jdbc,"WGC",at.plusSeconds(10),true).state());jdbc.update("UPDATE node_sample SET received_at=? WHERE node_id='WGWATER' AND sequence=2",java.sql.Timestamp.from(at.minusSeconds(1)));assertEquals("STALE",CircuitFlowGuard.inspect(jdbc,"WGC",at.plusSeconds(9),true).state());}
 @Test void otherStationAndDuplicatesDoNotRefreshFlow()throws Exception {flowPolicy();var r=running();afterGrace(r);flow(2,0.0,Instant.now());flow(2,99.0,Instant.now());jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('WGOTHER','Other','AREA001','WATER',2)");jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('WGOTHER','FLOW','FLOW_RATE','L/min')");var other=packet(1,true,Instant.now());other.put("deviceId","WGOTHER");other.withArray("readings").remove(0);router.store("smartfarm/FARM001/WGOTHER/telemetry",mapper.writeValueAsBytes(other));sessions.stopForFlow();assertEquals("LOW_FLOW",evidence().path("state").asText());jdbc.update("DELETE FROM iot_node WHERE node_id='WGOTHER'");}
 @Test void mqttUnavailableSavesOffWithoutRetry()throws Exception {flowPolicy();var r=running();afterGrace(r);flow(2,0.0,Instant.now());when(transport.controlConnected()).thenReturn(false);sessions.stopForFlow();var off=sessions.find("WGC",r.sessionId()).offId();assertEquals("FAILED",jdbc.queryForObject("SELECT state FROM pump_command WHERE command_id=?",String.class,off));assertEquals("RETURNED",sessions.operation("WGC",off).state());when(transport.controlConnected()).thenReturn(true);sessions.stopForFlow();assertEquals(1,stops());verify(transport,times(1)).publishCommand(any());}
 @Test void uncertainPublishIsNotRetriedAndEvidencePrecedesBytes()throws Exception {flowPolicy();var r=running();afterGrace(r);flow(2,0.0,Instant.now());doAnswer(a->{assertEquals(1,stops());assertTrue(sessions.find("WGC",r.sessionId()).stopRequested());throw new IllegalStateException();}).when(transport).publishCommand(any());sessions.stopForFlow();var off=sessions.find("WGC",r.sessionId()).offId();assertEquals("PUBLISH_UNCERTAIN",jdbc.queryForObject("SELECT state FROM pump_command WHERE command_id=?",String.class,off));sessions.stopForFlow();verify(transport,times(2)).publishCommand(any());}
 @Test void manualOffAndRestartSuppressFlowReplay()throws Exception {flowPolicy();var r=running();afterGrace(r);step(r,"OFF");sessions.stopForFlow();assertEquals(0,stops());clearInvocations(transport);sessions.interruptOnStartup();sessions.stopForFlow();verify(transport,never()).publishCommand(any());}
 @Test void restartAfterStopDoesNotReplayAndKeepsEvidence()throws Exception {flowPolicy();var r=running();afterGrace(r);flow(2,0.0,Instant.now());sessions.stopForFlow();var before=evidence();clearInvocations(transport);sessions.interruptOnStartup();sessions.stopForFlow();assertEquals(before,evidence());assertEquals("RECOVERY_REQUIRED",sessions.find("WGC",r.sessionId()).phase());verify(transport,never()).publishCommand(any());}
 @Test void flowAndWaterShareStopClaim()throws Exception {flowPolicy();gate.save("WGC",new CircuitWaterGate.Request(0,1,null,true,true));var r=running();afterGrace(r);flow(2,0.0,Instant.now());water(3,false,Instant.now());try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){for(var f:pool.invokeAll(List.<java.util.concurrent.Callable<Void>>of(()->{sessions.stopForFlow();return null;},()->{sessions.stopForWater();return null;})))f.get();}assertEquals(1,jdbc.queryForObject("SELECT (SELECT count(*) FROM irrigation_flow_stop)+(SELECT count(*) FROM irrigation_water_stop)",Integer.class));verify(transport,times(2)).publishCommand(any());}
 @Test void historyAndSnapshotAreGetOnlyAndScoped()throws Exception {flowPolicy();var r=running();afterGrace(r);flow(2,0.0,Instant.now());sessions.stopForFlow();clearInvocations(transport);mvc.perform(get("/api/v1/irrigation-circuits/WGC/flow-guard/stops")).andExpect(status().isOk()).andExpect(jsonPath("$.workerEnabled").value(true)).andExpect(jsonPath("$.items[0].evidence.state").value("LOW_FLOW"));mvc.perform(get("/api/v1/irrigation-circuits/WGC/flow-guard")).andExpect(status().isOk()).andExpect(jsonPath("$.state").value("IDLE"));mvc.perform(get("/api/v1/irrigation-circuits/OTHER/flow-guard/stops")).andExpect(status().isNotFound());verify(transport,never()).publishCommand(any());}
 @Test void disabledWorkerCannotClaimHealthyMode()throws Exception {flowPolicy();var r=running();afterGrace(r);assertEquals("MONITOR_DISABLED",CircuitFlowGuard.inspect(jdbc,"WGC",Instant.now(),false).state());assertFalse(CircuitFlowGuard.inspect(jdbc,"WGC",Instant.now(),false).stopRequired());}

 @Test void delayedFlowOffCannotTouchNewerManualStop()throws Exception {var guarded=spy(org.springframework.test.util.AopTestUtils.<PumpCommandFencing>getUltimateTargetObject(fencing));var local=new IrrigationSession(jdbc,mapper,circuits,valves,pump,guarded,proof,manager,true,false);local.interruptOnStartup();flowPolicy();var r=running();afterGrace(r);flow(2,0.0,Instant.now());doAnswer(a->{step(sessions.find("WGC",r.sessionId()),"OFF");return a.callRealMethod();}).when(guarded).createHttp(any(),any());local.stopForFlow();var automatic=jdbc.queryForObject("SELECT request_id FROM irrigation_flow_stop",UUID.class);assertEquals("UNRESOLVED",sessions.operation("WGC",automatic).state());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM pump_command WHERE command_id=?",Integer.class,automatic));verify(transport,times(2)).publishCommand(any());}
 @Test void missingIntentStillStoresUnresolvedStop()throws Exception {var guarded=spy(org.springframework.test.util.AopTestUtils.<PumpCommandFencing>getUltimateTargetObject(fencing));var local=new IrrigationSession(jdbc,mapper,circuits,valves,pump,guarded,proof,manager,true,false);local.interruptOnStartup();flowPolicy();var r=running();afterGrace(r);flow(2,0.0,Instant.now());var v=fencing.view();doReturn(new PumpCommandFencing.View(v.required(),v.deviceEnabled(),v.compatible(),v.restartRequired(),v.lastOrdinal(),null,v.ownership(),v.circuitRouteRequired(),v.circuitRoute())).when(guarded).view();local.stopForFlow();local.stopForFlow();var stopped=sessions.find("WGC",r.sessionId());assertEquals("RECOVERY_REQUIRED",stopped.phase());assertEquals("UNRESOLVED",sessions.operation("WGC",stopped.offId()).state());assertEquals(1,stops());verify(transport,times(1)).publishCommand(any());}
 @Test void calibrationDriftStopsAndDisabledPolicyCanBeReviewed(){flowPolicy();jdbc.update("UPDATE iot_channel SET calibration_version='NEW' WHERE node_id='WGWATER' AND channel_id='FLOW'");assertThrows(Exception.class,()->flowGuard.save("WGC",flowRequest(1,true)));assertFalse(flowGuard.save("WGC",flowRequest(1,false)).enabled());}
 @Test void flowStopNeverClosesValveOrInventsOffProof()throws Exception {flowPolicy();var r=running();afterGrace(r);flow(2,0.0,Instant.now());clearInvocations(valveTransport);sessions.stopForFlow();assertFalse(sessions.snapshot("WGC").canClose());assertFalse(sessions.snapshot("WGC").canFinish());verify(valveTransport,never()).publishCircuitValve(anyString(),any());}
}
